// iPhone ringtones (#1291) through the job queue with FFmpeg, from the converter to the note on the result. Runs only
// when Filee's FFmpeg is installed (`pwsh build/fetch-engines.ps1 -Only ffmpeg`). The sound is generated by FFmpeg
// itself and every output is checked with ffprobe.

using System.Globalization;
using System.Text.Json;
using Filee.Core.Conversion;
using Filee.Core.Presets;
using Filee.Engines.Infrastructure;
using Filee.Engines.Media;

namespace Filee.Engines.Tests;

[Collection(nameof(FfmpegCollection))]
public class RingtoneConversionTests(EngineFixture fx) : IClassFixture<EngineFixture>
{
    private static readonly (string Ffmpeg, string Ffprobe)? Tools = FfmpegConverter.Locate();

    private static void SkipUnlessInstalled() =>
        Assert.SkipUnless(Tools is not null, "FFmpeg is not installed (pwsh build/fetch-engines.ps1 -Only ffmpeg)");

    /// <summary>A tone of the given length, as a WAV.</summary>
    private static async Task<string> MakeSineAsync(string folder, string name, int seconds)
    {
        var path = Path.Combine(folder, name);
        var result = await ProcessRunner.RunAsync(Tools!.Value.Ffmpeg,
            ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i", $"sine=frequency=440:sample_rate=44100:duration={seconds}", "-ac", "2", path],
            TimeSpan.FromMinutes(2), CancellationToken.None);
        Assert.True(result.ExitCode == 0, result.StandardError);
        return path;
    }

    private static async Task<(string? AudioCodec, double Duration)> ProbeAsync(string path)
    {
        var result = await ProcessRunner.RunAsync(Tools!.Value.Ffprobe,
            ["-v", "error", "-print_format", "json", "-show_format", "-show_streams", path], TimeSpan.FromMinutes(1), CancellationToken.None);
        Assert.True(result.ExitCode == 0, $"ffprobe {path}: {result.StandardError}");
        using var json = JsonDocument.Parse(result.StandardOutput);
        var audio = json.RootElement.GetProperty("streams").EnumerateArray().FirstOrDefault(s => s.GetProperty("codec_type").GetString() == "audio");
        var codec = audio.ValueKind == JsonValueKind.Object ? audio.GetProperty("codec_name").GetString() : null;
        var duration = double.Parse(json.RootElement.GetProperty("format").GetProperty("duration").GetString()!, CultureInfo.InvariantCulture);
        return (codec, duration);
    }

    private async Task<ConversionJob> RunAsync(string source, Action<Preset>? change = null)
    {
        var preset = BuiltInData.CreatePresets().Single(p => p.Id == BuiltInData.RingtoneId);
        change?.Invoke(preset);
        var job = await fx.ConvertAsync([source], preset);
        Assert.True(job.State == JobState.Completed, string.Join("; ", job.Files.Select(f => $"{f.ErrorKey} {f.ErrorDetail}")));
        return job;
    }

    [Fact]
    public async Task The_built_in_preset_makes_an_M4R_of_thirty_seconds_and_the_result_says_it_is_a_part()
    {
        SkipUnlessInstalled();
        var source = await MakeSineAsync(fx.NewFolder(), "tone.wav", 60);

        var job = await RunAsync(source);

        var output = Assert.Single(job.Outputs);
        Assert.Equal(Path.Combine(Path.GetDirectoryName(source)!, "tone.m4r"), output);
        var (codec, duration) = await ProbeAsync(output);
        Assert.Equal("aac", codec);
        Assert.InRange(duration, 29.5, 30.6);
        Assert.Equal("notice.ringtone_cut", job.Files.Single().NoticeKey);
        Assert.True(File.Exists(source));
    }

    [Fact]
    public async Task A_ringtone_asked_to_be_longer_than_forty_seconds_comes_out_at_forty_with_the_note()
    {
        SkipUnlessInstalled();
        var source = await MakeSineAsync(fx.NewFolder(), "tone.wav", 60);

        var job = await RunAsync(source, preset => preset.Media.RingtoneLength = 90);

        var (codec, duration) = await ProbeAsync(Assert.Single(job.Outputs));
        Assert.Equal("aac", codec);
        Assert.InRange(duration, 39.5, 40.6);
        Assert.Equal("notice.ringtone_cut", job.Files.Single().NoticeKey);
    }

    [Fact]
    public async Task A_short_sound_becomes_a_ringtone_as_it_is_without_a_note()
    {
        SkipUnlessInstalled();
        var source = await MakeSineAsync(fx.NewFolder(), "chime.wav", 5);

        var job = await RunAsync(source);

        var (codec, duration) = await ProbeAsync(Assert.Single(job.Outputs));
        Assert.Equal("aac", codec);
        Assert.InRange(duration, 4.5, 5.6);
        Assert.Null(job.Files.Single().NoticeKey);
    }
}
